import hotel.rooms.Room;
import hotel.rooms.RoomType;
import java.math.BigDecimal;
import java.time.LocalDate;

public class DocumentExamples {
    public static void main(String[] args) {
        Room room = new Room(201, RoomType.DELUXE, new BigDecimal("389.90"), 2);

        // Individual (CPF)
        Guest individual = new Guest("Maria Silva", "maria@example.com", "123.456.789-00", null, null, null, null);
        Price price1 = new Price(2, new BigDecimal("779.80"), BigDecimal.ZERO, new BigDecimal("779.80"));
        NewReservation req1 = new NewReservation(201, individual, LocalDate.of(2027, 3, 10), LocalDate.of(2027, 3, 12), 2, RatePlan.STANDARD);
        Reservation res1 = new Reservation(1, req1, price1);
        ReservationReceipt receipt1 = new ReservationReceipt(res1, room);

        System.out.println("=== Comprovante (CPF) ===");
        System.out.println(receipt1.text());
        System.out.println();

        // Company (CNPJ)
        Guest company = new Guest("Ana Souza", "ana@example.com", null, "12.345.678/0001-90", "Tecnosul Ltda", null, null);
        Price price2 = new Price(2, new BigDecimal("779.80"), BigDecimal.ZERO, new BigDecimal("779.80"));
        NewReservation req2 = new NewReservation(201, company, LocalDate.of(2027, 3, 10), LocalDate.of(2027, 3, 12), 1, RatePlan.STANDARD);
        Reservation res2 = new Reservation(2, req2, price2);
        ReservationReceipt receipt2 = new ReservationReceipt(res2, room);

        System.out.println("=== Fatura de hospedagem (CNPJ) ===");
        System.out.println(receipt2.text());
        System.out.println();

        // Foreign (Passport)
        Guest foreign = new Guest("John Smith", "john@example.com", null, null, null, "X1234567", "United Kingdom");
        Price price3 = new Price(2, new BigDecimal("779.80"), BigDecimal.ZERO, new BigDecimal("779.80"));
        NewReservation req3 = new NewReservation(201, foreign, LocalDate.of(2027, 3, 10), LocalDate.of(2027, 3, 12), 2, RatePlan.STANDARD);
        Reservation res3 = new Reservation(3, req3, price3);
        ReservationReceipt receipt3 = new ReservationReceipt(res3, room);

        System.out.println("=== Booking receipt (Passport) ===");
        System.out.println(receipt3.text());
        System.out.println();

        // Test with 1 night for foreign
        Guest foreign1Night = new Guest("Jane Doe", "jane@example.com", null, null, null, "Y9876543", "United States");
        Price price4 = new Price(1, new BigDecimal("389.90"), BigDecimal.ZERO, new BigDecimal("389.90"));
